00237 // Parsing
00238 //
00239 std::istream &operator>>(std::istream &in, ImageFormat &v) {
00240     std::string s;
00241     in >> s;
00242     s = lowercase(s);
00243 
00244     if (s == "yuv")
00245         v = IMAGE_FORMAT_YUV420P8;
00246 
00247     else if (s == "yuv420")
00248         v = IMAGE_FORMAT_YUV420P8;
00249     else if (s == "yuv422")
00250         v = IMAGE_FORMAT_YUV422P8;
00251     else if (s == "yuv444")
00252         v = IMAGE_FORMAT_YUV444P8;
00253 
00254     else if (s == "yuv420p")
00255         v = IMAGE_FORMAT_YUV420P8;
00256     else if (s == "yuv422p")
00257         v = IMAGE_FORMAT_YUV422P8;
00258     else if (s == "yuv444p")
00259         v = IMAGE_FORMAT_YUV444P8;
00260 
00261     else if (s == "yuv420p8")
00262         v = IMAGE_FORMAT_YUV420P8;
00263     else if (s == "yuv422p8")
00264         v = IMAGE_FORMAT_YUV422P8;
00265     else if (s == "yuv444p8")
00266         v = IMAGE_FORMAT_YUV444P8;
00267 
00268     else if (s == "yuv420p10")
00269         v = IMAGE_FORMAT_YUV420P10;
00270     else if (s == "yuv422p10")
00271         v = IMAGE_FORMAT_YUV422P10;
00272     else if (s == "yuv444p10")
00273         v = IMAGE_FORMAT_YUV444P10;
00274 
00275     else if (s == "yuv420p12")
00276         v = IMAGE_FORMAT_YUV420P12;
00277     else if (s == "yuv422p12")
00278         v = IMAGE_FORMAT_YUV422P12;
00279     else if (s == "yuv444p12")
00280         v = IMAGE_FORMAT_YUV444P12;
00281 
00282     else if (s == "yuv420p14")
00283         v = IMAGE_FORMAT_YUV420P14;
00284     else if (s == "yuv422p14")
00285         v = IMAGE_FORMAT_YUV422P14;
00286     else if (s == "yuv444p14")
00287         v = IMAGE_FORMAT_YUV444P14;
00288 
00289     else if (s == "yuv420p16")
00290         v = IMAGE_FORMAT_YUV420P16;
00291     else if (s == "yuv422p16")
00292         v = IMAGE_FORMAT_YUV422P16;
00293     else if (s == "yuv444p16")
00294         v = IMAGE_FORMAT_YUV444P16;
00295 
00296     else if (s == "y")
00297         v = IMAGE_FORMAT_Y8;
00298     else if (s == "y8")
00299         v = IMAGE_FORMAT_Y8;
00300     else if (s == "y10")
00301         v = IMAGE_FORMAT_Y10;
00302     else if (s == "y12")
00303         v = IMAGE_FORMAT_Y12;
00304     else if (s == "y14")
00305         v = IMAGE_FORMAT_Y14;
00306     else if (s == "y16")
00307         v = IMAGE_FORMAT_Y16;
00308 
00309     else if (s == "yuv400")
00310         v = IMAGE_FORMAT_Y8;
00311     else if (s == "yuv400p")
00312         v = IMAGE_FORMAT_Y8;
00313     else if (s == "yuv400p10")
00314         v = IMAGE_FORMAT_Y10;
00315     else if (s == "yuv400p12")
00316         v = IMAGE_FORMAT_Y12;
00317     else if (s == "yuv400p14")
00318         v = IMAGE_FORMAT_Y14;
00319     else if (s == "yuv400p16")
00320         v = IMAGE_FORMAT_Y16;
00321     else
00322         ERR("not an image format: %s", s.c_str());
00323 
00324     return in;
00325 }
00326 
00327 std::istream &operator>>(std::istream &in, Colourspace &v) {
00328     ImageFormat f;
00329     in >> f;
00330 
00331     CHECK(f < ARRAY_SIZE(s_PictureDescInfo));
00332 
00333     v = s_PictureDescInfo[f].colourspace;
00334 
00335     return in;
00336 }
